// وحين تعرضه للمستخدمين: يُرسل cookies الجميع للمهاجم!

// ✅ React: آمن تلقائياً — JSX يُهرّب النص
<p>{userComment}</p>   // آمن: يعرض النص حرفياً

// ✅ إذا احتجت HTML خاماً: استخدم DOMPurify
